  TreeNode<T> parent = node.getParent();
  if (parent == null) {
    return null;
  }

  TreeNode<T> leftChild = node.getLeftChild();
  TreeNode<T> rightChild = node.getRightChild();
  if (leftChild == null) {
    return null;
  }

  leftChild.setParent(parent);
  rightChild.setParent(leftChild);

  node.setLeftChild(rightChild);
  node.setRightChild(leftChild.getLeftChild());
  leftChild.setLeftChild(node);

  return leftChild;
}

