public Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (genericType instanceof ParameterizedType) {
        ParameterizedType parameterizedType = (ParameterizedType) genericType;
        Type[] typeArguments = parameterizedType.getActualTypeArguments();
        if (targetType.isAssignableFrom(parameterizedType.getRawType())) {
            TypeVariable<?>[] typeParameters = parameterizedType.getRawType().getTypeParameters();
            if (typeArguments.length == typeParameters.length) {
                Class<?>[] resolvedArguments = new Class<?>[typeArguments.length];
                for (int i = 0; i < typeArguments.length; i++) {
                    resolvedArguments[i] = findConcreteType(typeArguments[i], typeParameters[i], targetType);
                }
                return resolvedArguments;
            }
        }
    }
    return null;
}

private static Class<?> findConcreteType(Type type, TypeVariable<?> variable, Class<?> targetType) {
    if (type instanceof Class) {
        return (Class<?>) type;
    }
    if (type instanceof ParameterizedType) {
        ParameterizedType parameterizedType = (ParameterizedType) type;
        if (parameterizedType.getRawType().equals(targetType)) {
            Type[] typeArguments = parameterizedType.getActualTypeArguments();
            for (int i = 0; i < typeArguments.length; i++) {
                if (typeArguments[i].equals(variable)) {
                    return (Class<?>) typeArguments[i];
                }
            }
        }
    }
    return null;
}

