static long compressTimeBucket(long timeBucket, int dayStep) {
    // Convert the timeBucket to a string
    String timeString = Long.toString(timeBucket);

    // Extract the day of the month from the timeString
    String dayOfMonth = timeString.substring(6, 10);

    // Convert the dayStep to a string
    String stepString = Integer.toString(dayStep);

    // Subtract 1 from the dayStep if it's not 1
    if (Integer.parseInt(stepString) != 1) {
        stepString = Integer.toString(Integer.parseInt(stepString) - 1);
    }

    // Split the day of the month into an array of characters
    char[] dayOfMonthArray = dayOfMonth.toCharArray();

    // Modify the last digit of the day of the month based on the stepString
    dayOfMonthArray[dayOfMonthArray.length - 1] += Integer.parseInt(stepString);

    // Join the modified day of the month and the year
    String newDayOfMonth = String.join("", dayOfMonthArray);
    String newTimeBucket = newDayOfMonth + timeString.substring(10, 14);

    // Convert the new timeBucket to a long and return it
    return Long.parseLong(newTimeBucket);
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    intutf8Size = 0;
    for (int i = index; i < index + len; i++) {
        int codePoint = str.codePointAt(i);
        if (codePoint <= 0x7F) {
            utf8Size += 1;
        } else if (codePoint <= 0x7FF) {
            utf8Size += 2;
        } else if (codePoint <= 0xFFFF) {
            utf8Size += 3;
        } else if (codePoint <= 0x1FFFFF) {
            utf8Size += 4;
        } else if (codePoint <= 0x3FFFFFF) {
            utf8Size += 5;
        } else if (codePoint <= 0x7FFFFFFF) {
            utf8Size += 6;
        } else {
            throw new IllegalArgumentException("Code point not valid: " + codePoint);
        }
    }
    return utf8Size;
}

