                this.head.prev = null;
            }
            result = true;
        } else if (this.tail == node) {
            this.tail = node.prev;
            if (this.tail != null) {
                this.tail.next = null;
            }
            result = true;
        } else {
            ListNodeImpl<E> prev = node.prev;
