    if (str == null || str.isEmpty()) {
        return str;
    }

    // Find the first non-leading character in the String
    int firstNonLeadingIndex = 0;
    for (int i = 0; i < str.length(); i++) {
        if (str.charAt(i) != leadingCharacter) {
            firstNonLeadingIndex = i;
            break;
        }
    }

    // If all characters in the String are leading characters, return an empty String
    if (firstNonLeadingIndex == 0) {
        return "";
    }

    // Return the substring of the original String starting from the first non-leading character
    return str.substring(firstNonLeadingIndex);
}

